<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import type { OrderDetail } from '@express-platform/shared-types';
import { adminApi } from '../services/api';
import { errorMessage, formatTime, money, statusLabel } from '../utils';

const route=useRoute(); const router=useRouter(); const order=ref<OrderDetail|null>(null); const loading=ref(true); const error=ref('');
const sender=computed(()=>order.value?.addresses.find((a)=>a.type==='SENDER')); const recipient=computed(()=>order.value?.addresses.find((a)=>a.type==='RECIPIENT'));
onMounted(()=>void load()); async function load():Promise<void>{loading.value=true;error.value='';try{order.value=await adminApi.order(String(route.params.id));}catch(cause:unknown){error.value=errorMessage(cause);}finally{loading.value=false;}}
</script>
<template><div><div class="page-head"><div><button class="back-link" @click="router.push('/orders')">← 返回订单调度</button><h1 class="page-title">订单详情</h1><p class="page-subtitle">完整状态日志、寄收信息与 Mock 物流轨迹</p></div><button class="secondary" @click="load">刷新状态</button></div>
  <div v-if="loading" class="panel state"><strong>正在加载订单</strong>同步完整状态日志…</div><div v-else-if="error" class="panel state error"><strong>加载失败</strong>{{error}}</div>
  <template v-else-if="order"><section class="detail-hero"><div><span>ORDER STATUS</span><h2>{{statusLabel[order.status]}}</h2><p>{{order.orderNo}} · {{order.shipment?.shipmentNo??'待生成运单'}}</p></div><div><small>预估费用</small><strong>{{money(order.estimatedFee,order.currency)}}</strong></div></section>
    <div class="detail-grid"><section class="panel address-panel"><h3>寄收路线</h3><div class="address"><i class="from">寄</i><div><strong>{{sender?.contactName}} · {{sender?.phone}}</strong><p>{{sender?.city}} {{sender?.district}} {{sender?.detail}}</p></div></div><div class="stem"></div><div class="address"><i>收</i><div><strong>{{recipient?.contactName}} · {{recipient?.phone}}</strong><p>{{recipient?.city}} {{recipient?.district}} {{recipient?.detail}}</p></div></div></section><section class="panel basic-panel"><h3>业务信息</h3><dl><dt>服务类型</dt><dd>{{order.serviceType}}</dd><dt>预约上门</dt><dd>{{formatTime(order.scheduledPickupAt)}}</dd><dt>物品</dt><dd>{{order.items[0]?.name}} · {{order.items[0]?.weightKg}} kg</dd><dt>配送任务</dt><dd>{{order.task?.status??'未生成'}}</dd></dl></section></div>
    <div class="log-grid"><section class="panel log-panel"><h3>状态日志 <small>{{order.statusLogs.length}} 条</small></h3><div v-for="log in [...order.statusLogs].reverse()" :key="log.id" class="log-item"><i></i><div><strong>{{statusLabel[log.toStatus]}}</strong><p>{{log.reason??'状态更新'}}</p><small>{{log.operatorType}} · {{formatTime(log.createdAt)}}</small></div></div></section><section class="panel log-panel"><h3>物流轨迹 <small>{{order.shipment?.trackingEvents.length??0}} 条</small></h3><div v-if="!order.shipment?.trackingEvents.length" class="mini-empty">调度后生成 Mock 物流轨迹。</div><div v-for="event in [...(order.shipment?.trackingEvents??[])].reverse()" v-else :key="event.id" class="log-item tracking"><i></i><div><strong>{{statusLabel[event.status]}}</strong><p>{{event.description}}</p><small>{{formatTime(event.occurredAt)}}</small></div></div></section></div>
  </template></div></template>
<style scoped>
.back-link { margin:0 0 12px; padding:0; color:#d75b26; border:0; background:transparent; font-size:11px; font-weight:800; }.detail-hero { display:flex; align-items:center; justify-content:space-between; padding:28px 32px; border-radius:20px; color:#fff; background:linear-gradient(135deg,#2c2824,#494039); }.detail-hero span { color:#e89a75; font-size:9px; letter-spacing:2px; }.detail-hero h2 { margin:9px 0 5px; font-size:31px; }.detail-hero p { margin:0; color:#cfc6bd; font-size:12px; }.detail-hero>div:last-child { text-align:right; }.detail-hero small,.detail-hero strong { display:block; }.detail-hero small { color:#c8bdb4; font-size:10px; }.detail-hero>div:last-child strong { margin-top:7px; color:#ffb089; font-size:20px; }.detail-grid,.log-grid { display:grid; grid-template-columns:1.25fr .75fr; gap:20px; margin-top:20px; }.log-grid { grid-template-columns:1fr 1fr; }.address-panel,.basic-panel,.log-panel { padding:25px; }.address-panel h3,.basic-panel h3,.log-panel h3 { margin:0 0 22px; font-size:15px; }.address { display:flex; gap:13px; }.address i { flex:none; display:grid; place-items:center; width:36px; height:36px; border-radius:11px; color:#fff; background:#35302b; font-style:normal; font-size:11px; font-weight:900; }.address i.from { background:#ea652f; }.address strong { font-size:13px; }.address p { margin:6px 0 0; color:#7f756d; font-size:11px; }.stem { width:2px; height:28px; margin:3px 0 3px 17px; background:#ddd3ca; }.basic-panel dl { display:grid; grid-template-columns:90px 1fr; gap:17px 10px; margin:0; font-size:11px; }.basic-panel dt { color:#8b8178; }.basic-panel dd { margin:0; text-align:right; font-weight:700; }.log-panel h3 small { margin-left:6px; color:#91877f; font-weight:400; }.log-item { display:grid; grid-template-columns:14px 1fr; gap:12px; min-height:90px; }.log-item i { width:11px; height:11px; margin-top:3px; border:3px solid #ed6a32; border-radius:50%; box-shadow:0 0 0 5px #fff0e7; }.log-item strong { font-size:12px; }.log-item p { margin:5px 0; color:#776e66; font-size:11px; }.log-item small { color:#a0978f; font-size:9px; }.tracking i { border-color:#3b856c; box-shadow:0 0 0 5px #eaf5f0; }.mini-empty { padding:30px; color:#8c8279; text-align:center; font-size:11px; }
</style>
